<div class="process-card"><h2>Lịch sử xử lý & tài liệu</h2>@forelse($run->events as $event)<article class="process-event"><strong>{{ $event->actionLabel() }}</strong> · {{ $event->actor?->name }} · {{ $event->created_at->format('d/m/Y H:i') }}<div style="white-space:pre-wrap">{{ $event->note }}</div>@foreach($event->documents as $document)<div class="mt-1"><a href="{{ route('process-documents.download',$document) }}">{{ $document->original_name }}</a><div class="small text-muted">{{ $document->uploader?->name }} · {{ $document->created_at->format('d/m/Y H:i') }}</div></div>@endforeach<details class="small mt-2"><summary>Số liệu tại thời điểm xử lý</summary>@if(isset($event->snapshot['total']))<div>Tổng phí: {{ number_format($event->snapshot['total'],0,',','.') }}đ</div>@foreach($event->snapshot['items']??[] as $item)<div>Đơn #{{ $item['order_id'] }}: {{ number_format($item['amount'],0,',','.') }}đ · {{ $item['note']??'' }}</div>@endforeach @else<div style="white-space:pre-wrap">{{ $event->snapshot['note']??'' }}</div>@foreach($event->snapshot['subjects']??[] as $subject)<div>{{ $subject['subject_type']==='order'?'Đơn hàng':'Sản phẩm' }} {{ $subject['label']??('#'.$subject['subject_id']) }}</div>@endforeach @endif</details></article>@empty<p class="text-muted">Chưa có lịch sử.</p>@endforelse</div>
